namespace Jeninnet.Validation.OpenApi.Swashbuckle;

/// <summary>
/// Applies Jeninnet.Validation constraints to schemas generated by Swashbuckle.
/// </summary>
/// <param name="registry">The descriptor registry.</param>
public sealed class JeninnetValidationSchemaFilter(ValidationSchemaRegistry registry) : ISchemaFilter {
    private readonly ValidationSchemaRegistry _registry =
        registry ?? throw new ArgumentNullException(nameof(registry));

    /// <summary>
    /// Applies the constraints for the object type currently being generated. Property-level
    /// filters are skipped because the same constraints are applied once at the object level;
    /// referenced schemas are handled by the filter that runs for their own type definition.
    /// </summary>
    /// <param name="schema">The generated schema.</param>
    /// <param name="context">The schema generation context.</param>
    /// <exception cref="ArgumentNullException"><paramref name="schema"/> or <paramref name="context"/> is null.</exception>
    public void Apply(IOpenApiSchema schema, SchemaFilterContext context) {
        ArgumentNullException.ThrowIfNull(schema);
        ArgumentNullException.ThrowIfNull(context);

        if(schema is not OpenApiSchema concrete || concrete.Properties is not { Count: > 0 } properties) {
            return;
        }

        if(context.MemberInfo is not null) {
            return;
        }

        if(!_registry.TryGet(context.Type, out var descriptor) || descriptor is null) {
            return;
        }

        foreach(var member in descriptor.Members) {
            var constraints = ValidationSchemaMapper.MapMember(member);
            var propertyName = SchemaPropertyNameResolver.Resolve(context.Type, properties.Keys, member.Name);

            if(propertyName is null) {
                continue;
            }

            if(IsRequired(constraints)) {
                concrete.Required ??= new HashSet<string>(StringComparer.Ordinal);
                concrete.Required.Add(propertyName);
            }

            if(properties.TryGetValue(propertyName, out var propertySchema) &&
               propertySchema is OpenApiSchema propertyConcrete) {
                SwashbuckleSchemaConstraintWriter.Apply(constraints, propertyConcrete);
            }
        }
    }

    private static bool IsRequired(ValidationSchemaConstraints constraints) {
        if(!constraints.IsRequired) {
            return false;
        }

        var memberType = constraints.MemberType;
        if(memberType is null) {
            return true;
        }

        return Nullable.GetUnderlyingType(memberType) is not null || !memberType.IsValueType;
    }
}
